allow src/agent_box/server/services.py
allow src/agent_box/server/records.py
allow src/agent_box/server/persistence.py
allow src/agent_box/server/errors.py
deny src/agent_box/server/execution
deny src/agent_box/server/bootstrap
deny src/agent_box/server/wire
deny src/agent_box/server/credentials.py
deny src/agent_box/server/credential_cli.py
deny src/agent_box/server/events

